/**

diffs.newText:
 * @returns {Readonly<object>} The reversing entry.
 */
reverse(entryId, options) {
  const original = this.#entriesById.get(entryId);
  if (!original) throw new LedgerError('NOT_FOUND', `unknown entry: ${entryId}`);
  if (original.reverses !== null) throw new LedgerError('REVERSAL_OF_REVERSAL', `entry is itself a reversal: ${entryId}`);
  if (this.#reversedBy.get(entryId)) {
    throw new LedgerError('ALREADY_REVERSED', `entry already reversed: ${entryId}`);
  }
  const { id, at, memo } = options ?? {};
  if (isNonNegativeInteger(at) && at < original.at) {
    throw new LedgerError('BAD_TIME', 'reversal cannot precede the entry it reverses');
  }
  const reversal = this.#post(
    {
      id,
      at,
      memo: memo === undefined ? `reversal of ${entryId}` : memo,
      lines: original.lines.map((line) => ({ account: line.account, amountCents: -line.amountCents })),
    },
    entryId,
  );
  this.#reversedBy.set(entryId, reversal.id);
  return reversal;
}

