   * @returns {Array<{entryId: string, at: number, seq: number, amountCents: number, balanceCents: number}>} Statement rows.
   */
  statement(accountId, options = {}) {
    this.#requireAccount(accountId);
    const { from = -Infinity, to = Infinity } = options;
    const ids = this.#orderedIds({ asOf: Infinity });
    const rows = [];
    let running = 0;
    for (const id of ids) {
      const stored = this.#entriesById.get(id);
      for (const line of stored.lines) {
        if (line.account !== accountId) continue;
        running += line.amountCents;
        if (stored.at >= from && stored.at <= to) {
          rows.push({
            entryId: stored.id,
            at: stored.at,
            seq: stored.seq,
            amountCents: line.amountCents,
            balanceCents: running,
          });
        }
      }
    }
    return rows;
  }
